// aim.cpp
// Builds standalone with: cl /EHsc /std:c++17 /DSMOKE_TEST aim.cpp
// Exports:
//   WorldToScreen        – projects a 3-D world position to 2-D screen coords
//   GetEntityHeadPos     – reads an entity's head position from memory
//   ComputeSmoothedDelta – returns a smoothed crosshair delta inside a 240 px cone

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <algorithm>
#include <cstring>

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };

struct Matrix4x4 {
    float m[4][4];
};

struct ViewSetup {
    Matrix4x4 viewProjection; // combined view-projection matrix (column-major)
    int        screenW;
    int        screenH;
};

// ---------------------------------------------------------------------------
// WorldToScreen
//
// Projects `world` through `vs.viewProjection` and writes the result to
// `screen`.  Returns true when the point is in front of the camera.
// ---------------------------------------------------------------------------

bool WorldToScreen(const Vec3& world, const ViewSetup& vs, Vec2& screen)
{
    const float* m = &vs.viewProjection.m[0][0];

    // Homogeneous clip-space coordinates
    float clipX = m[0]  * world.x + m[4]  * world.y + m[8]  * world.z + m[12];
    float clipY = m[1]  * world.x + m[5]  * world.y + m[9]  * world.z + m[13];
    float clipW = m[3]  * world.x + m[7]  * world.y + m[11] * world.z + m[15];

    if (clipW < 0.001f)
        return false; // behind the camera

    float ndcX = clipX / clipW;
    float ndcY = clipY / clipW;

    screen.x = (ndcX  *  0.5f + 0.5f) * static_cast<float>(vs.screenW);
    screen.y = (-ndcY *  0.5f + 0.5f) * static_cast<float>(vs.screenH);
    return true;
}

// ---------------------------------------------------------------------------
// GetEntityHeadPos
//
// Reads a Vec3 head position from `entityBase + offset` via ReadProcessMemory.
// Returns false when the read fails.
// ---------------------------------------------------------------------------

bool GetEntityHeadPos(HANDLE hProcess, uintptr_t entityBase,
                      uintptr_t headOffset, Vec3& outPos)
{
    SIZE_T bytesRead = 0;
    return ReadProcessMemory(
        hProcess,
        reinterpret_cast<LPCVOID>(entityBase + headOffset),
        &outPos,
        sizeof(Vec3),
        &bytesRead
    ) && (bytesRead == sizeof(Vec3));
}

// ---------------------------------------------------------------------------
// ComputeSmoothedDelta
//
// Given the current crosshair position (`crosshair`) and the projected screen
// position of the target's head (`targetScreen`), returns a smoothed movement
// delta.  The delta is zeroed when the target lies outside a 240 px radius
// cone.  `smoothFactor` in [0, 1]: 0 = no movement, 1 = instant snap.
// ---------------------------------------------------------------------------

static constexpr float CONE_RADIUS_PX = 240.0f;

Vec2 ComputeSmoothedDelta(const Vec2& crosshair,
                          const Vec2& targetScreen,
                          float       smoothFactor)
{
    smoothFactor = std::clamp(smoothFactor, 0.0f, 1.0f);

    Vec2  raw   = { targetScreen.x - crosshair.x,
                    targetScreen.y - crosshair.y };
    float dist  = std::sqrtf(raw.x * raw.x + raw.y * raw.y);

    // Outside the engagement cone → no movement
    if (dist > CONE_RADIUS_PX)
        return { 0.0f, 0.0f };

    // Lerp the crosshair toward the target
    return { raw.x * smoothFactor, raw.y * smoothFactor };
}

// ---------------------------------------------------------------------------
// Smoke test – enabled when compiled with /DSMOKE_TEST
// ---------------------------------------------------------------------------

#ifdef SMOKE_TEST
#include <cstdio>

int main()
{
    // Build an orthographic-style view-projection that maps world units
    // to NDC with no perspective (w == 1 always) so the projection math
    // is easy to verify by hand.
    ViewSetup vs{};
    vs.screenW = 1920;
    vs.screenH = 1080;
    // Identity-ish matrix: scale xy by 1, z passthrough, w row = 0 0 0 1
    std::memset(&vs.viewProjection, 0, sizeof(vs.viewProjection));
    vs.viewProjection.m[0][0] = 1.f;  // row 0 col 0
    vs.viewProjection.m[1][1] = 1.f;
    vs.viewProjection.m[2][2] = 1.f;
    vs.viewProjection.m[3][3] = 1.f;

    Vec3 world{ 0.f, 0.f, 5.f };
    Vec2 screen{};
    bool visible = WorldToScreen(world, vs, screen);

    std::printf("WorldToScreen test:\n");
    std::printf("  visible = %s\n", visible ? "true" : "false");
    std::printf("  screen  = (%.1f, %.1f)\n", screen.x, screen.y);
    // Expected: NDC = (0,0) → screen = (960, 540)

    Vec2 crosshair   = { 960.f, 540.f };
    Vec2 target      = { 1080.f, 490.f }; // within 240 px
    Vec2 deltaIn     = ComputeSmoothedDelta(crosshair, target, 0.1f);

    std::printf("\nComputeSmoothedDelta (in-cone, factor=0.10):\n");
    std::printf("  delta = (%.2f, %.2f)\n", deltaIn.x, deltaIn.y);

    Vec2 targetFar   = { 1300.f, 540.f }; // 340 px away → outside cone
    Vec2 deltaOut    = ComputeSmoothedDelta(crosshair, targetFar, 0.1f);

    std::printf("\nComputeSmoothedDelta (out-of-cone, factor=0.10):\n");
    std::printf("  delta = (%.2f, %.2f)  [expected 0, 0]\n",
                deltaOut.x, deltaOut.y);

    return 0;
}
#endif // SMOKE_TEST
